package macro;
import star.common.*;import star.base.report.*;import star.vof.*;import star.material.*;import java.nio.file.*;
public class MiniVofVerify extends StarMacro {public void execute(){Simulation s=getActiveSimulation();Path d=Paths.get(System.getenv("MINI_CASE_DIR"));try{long cells=((FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh")).getCellCount();double t=s.getSolution().getPhysicalTime(),p=s.getReportManager().getReport("pABS_min").getReportMonitorValue();PhysicsContinuum pc=(PhysicsContinuum)s.getContinuumManager().getContinuum("MINI_URANS_VOF_2D");FirstOrderVofWave w=(FirstOrderVofWave)pc.getModelManager().getModel(VofWaveModel.class).getVofWaveManager().getVofWave("MINI_FirstOrder");if(!s.getSolution().isInitialized()||cells!=41280||!Double.isFinite(t+p)||t<=0||s.getNumberOfGpgpus()!=0)throw new IllegalStateException("Checkpoint read verification failed");String json="{\"status\":\"CHECKPOINT_READ_VERIFIED\",\"cells\":"+cells+",\"physical_time_s\":"+t+",\"pABS_min_Pa\":"+p+",\"wave_amplitude_m\":"+w.getAmplitude().getSIValue()+",\"wave_length_m\":"+w.getVofWaveSpecification().getWaveLength().getSIValue()+",\"wave_water_density\":"+w.getHeavyFluidDensity().getSIValue()+",\"wave_air_density\":"+w.getLightFluidDensity().getSIValue()+",\"fields_initialized\":true,\"solver_started\":false,\"reset\":false}";Files.writeString(d.resolve("SOLVE_STATUS.json"),json);}catch(Exception e){throw new RuntimeException(e);}}}
